const b = $json.body ?? $json;
const txt = (v, max) => String(v ?? '').trim().slice(0, max);
const entero = (v) => Number.parseInt(v, 10) || 0;
const fecha = (v) => /^\d{4}-\d{2}-\d{2}$/.test(String(v ?? '')) ? String(v) : '';
const accion = txt(b.accion ?? b.action, 40).toLowerCase();
const session_token = txt(b.session_token, 200);

const FRONTEND_URL = 'http://localhost:3000'; // cámbialo cuando tengas dominio
const ADMIN_EMAIL = 'milenahoyossss@gmail.com';
const RESULTADOS = ['Resuelto', 'Requiere nueva visita', 'No resuelto'];
const ACCIONES = ['cola_tecnico', 'agenda', 'iniciar_visita', 'registrar_resultado', 'datos_acta',
                  'adjuntar_acta', 'horarios_libres', 'asignar_tecnico'];

// Semana actual (lunes a domingo, hora Colombia) si no se envían fechas
const hoy = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Bogota' }));
const lunes = new Date(hoy); lunes.setDate(hoy.getDate() - ((hoy.getDay() + 6) % 7));
const domingo = new Date(lunes); domingo.setDate(lunes.getDate() + 6);
const iso = (f) => `${f.getFullYear()}-${String(f.getMonth() + 1).padStart(2, '0')}-${String(f.getDate()).padStart(2, '0')}`;

const d = {
  accion, session_token,
  ticket_id: entero(b.ticket_id),
  tecnico_id: entero(b.tecnico_id),
  desde: fecha(b.desde) || iso(lunes),
  hasta: fecha(b.hasta) || iso(domingo),
  fecha_inicio: txt(b.fecha_inicio, 40),
  diagnostico: txt(b.diagnostico, 4000),
  trabajo_realizado: txt(b.trabajo_realizado, 4000),
  repuestos: txt(b.repuestos, 1000),
  resultado: txt(b.resultado, 30),
  observaciones: txt(b.observaciones, 2000),
  archivo: txt(b.archivo, 120),
  sha256: txt(b.sha256, 64).toLowerCase(),
  pdf_base64: String(b.pdf_base64 ?? ''),
  frontend_url: FRONTEND_URL,
  admin_email: ADMIN_EMAIL,
};

let error = '', status = 'invalid';
if (!ACCIONES.includes(accion)) error = 'Acción no válida.';
else if (!session_token) { error = 'Inicia sesión para continuar.'; status = 'unauthorized'; }
else if (['iniciar_visita', 'registrar_resultado', 'datos_acta', 'adjuntar_acta', 'asignar_tecnico'].includes(accion) && d.ticket_id < 1)
  error = 'Número de ticket inválido.';
else if (accion === 'registrar_resultado' && d.diagnostico.length < 5) error = 'Escribe el diagnóstico (mínimo 5 caracteres).';
else if (accion === 'registrar_resultado' && d.trabajo_realizado.length < 5) error = 'Describe el trabajo realizado (mínimo 5 caracteres).';
else if (accion === 'registrar_resultado' && !RESULTADOS.includes(d.resultado)) error = 'Selecciona el resultado de la visita.';
else if (accion === 'adjuntar_acta' && !/^ticket-\d+-[0-9a-f]{24}\.pdf$/.test(d.archivo)) error = 'Nombre de acta no válido.';
else if (accion === 'adjuntar_acta' && !/^[0-9a-f]{64}$/.test(d.sha256)) error = 'Huella del acta no válida.';
else if (accion === 'adjuntar_acta' && !d.pdf_base64.startsWith('JVBER')) error = 'El acta debe ser un PDF.';
else if (['horarios_libres', 'asignar_tecnico'].includes(accion) && d.tecnico_id < 1) error = 'Selecciona un técnico.';
else if (accion === 'asignar_tecnico' && Number.isNaN(Date.parse(d.fecha_inicio))) error = 'Selecciona la fecha y hora de la visita.';
if (accion === 'asignar_tecnico' && !error) d.fecha_inicio = new Date(d.fecha_inicio).toISOString();

return [{ json: { ...d, ruta: error ? 'invalido' : 'sesion', error, status } }];

const req = $('Validar petición de operación').first().json;
const s = $input.first().json;
const permisos = {"cola_tecnico": ["tecnico"], "agenda": ["tecnico", "admin"], "iniciar_visita": ["tecnico"], "registrar_resultado": ["tecnico"], "datos_acta": ["tecnico", "admin"], "adjuntar_acta": ["tecnico", "admin"], "horarios_libres": ["admin"], "asignar_tecnico": ["admin"]};
let ruta = req.accion, status = 'ok', message = '';
if (!s.usuario_id) {
  ruta = 'denegado'; status = 'unauthorized'; message = 'Tu sesión expiró o no es válida. Inicia sesión nuevamente.';
} else if (!(permisos[req.accion] || []).includes(s.rol)) {
  ruta = 'denegado'; status = 'forbidden'; message = 'Tu cuenta no tiene permiso para esta acción.';
} else if (s.rol === 'tecnico' && !s.tecnico_id) {
  ruta = 'denegado'; status = 'forbidden'; message = 'Tu usuario técnico no está activo en la tabla de técnicos.';
}
return [{ json: { ...req, ruta, status, message,
  auth_usuario_id: Number(s.usuario_id || 0), auth_nombre: s.nombre_completo || '', auth_correo: s.correo || '',
  auth_rol: s.rol || '', auth_tecnico_id: Number(s.tecnico_id || 0) } }];

