WITH t0 AS (
  SELECT t.id FROM public.tickets_soporte t
   WHERE t.id = $1 AND t.tecnico_asignado_id = $2 AND t.estado = 'Agendado'
   FOR UPDATE
), upd AS (
  UPDATE public.tickets_soporte t SET estado = 'En atención' FROM t0 WHERE t.id = t0.id RETURNING t.id
), cita AS (
  UPDATE public.citas c SET hora_llegada = now()
   WHERE c.ticket_id IN (SELECT id FROM upd) AND c.estado = 'Agendada'
), audit AS (
  INSERT INTO public.auditoria_tickets (ticket_id, actor, accion, estado_anterior, estado_nuevo, detalle)
  SELECT id, 'tecnico:' || $2, 'inicio_visita', 'Agendado', 'En atención', jsonb_build_object('hora_llegada', now()) FROM upd
)
SELECT (SELECT id FROM upd) AS ticket_id, now() AS hora_llegada;

