// El PDF llega en base64 desde server.js; se adjunta al correo del cliente.
const fila = $input.first().json;
const req = $('Validar petición de operación').first().json;
if (!fila.ticket_id) return [{ json: { ...fila, enviar: false } }];
return [{
  json: { ...fila, enviar: true, resuelto: fila.resultado === 'Resuelto' },
  binary: { acta: { data: req.pdf_base64, mimeType: 'application/pdf', fileName: `acta-servicio-ticket-${fila.ticket_id}.pdf` } },
}];

const x = $input.first().json;
if (!x.ticket_id) {
  return [{ json: { enviar: false, respuesta: { success: false, status: 'assignment_rejected',
    message: 'No se pudo asignar: revisa que el ticket esté pendiente y que el horario esté libre en la disponibilidad del técnico (horario laboral, sin ausencias ni otra cita).' } } }];
}
const fecha_local = new Date(x.fecha_visita).toLocaleString('es-CO', { timeZone: 'America/Bogota', dateStyle: 'full', timeStyle: 'short' });
return [{ json: { ...x, fecha_local, enviar: true, respuesta: { success: true, status: 'appointment_scheduled',
  ticket_id: x.ticket_id, fecha_visita: x.fecha_visita, tecnico_nombre: x.tecnico_nombre,
  message: `Visita asignada a ${x.tecnico_nombre} para el ${fecha_local} (hora Colombia)` } } }];
